#!/usr/bin/env bash
set -euo pipefail

stage=${1:?usage: evaluate_candidate.sh feedback|final cNNN}
candidate=${2:?usage: evaluate_candidate.sh feedback|final cNNN}

export KDA_WORKSPACE=/home/ziming/kda-ops/kda-runs/formal-kda-h100-20260920--sol_execbench--L2-040_altup_predict_correction_cycle_backward
exec /home/ziming/kda-ops/bin/kda-eval "$stage" --candidate "$candidate"

