    "grad_hidden_states": {
        "shape": [
            "altup_num_inputs",
            "batch_size",
            "seq_len",
            "hidden_size"
        ],
        "dtype": "bfloat16",
        "description": "Gradient w.r.t. hidden states"
    },
    "grad_activated": {
        "shape": [
            "batch_size",
            "seq_len",
            "hidden_size"
        ],
        "dtype": "bfloat16",
        "description": "Gradient w.r.t. activated output"
    },
    "grad_prediction_coef_weight": {
        "shape": [
            "altup_num_inputs_sq",
            "altup_num_inputs"
        ],
        "dtype": "float32",
        "description": "Gradient w.r.t. prediction coefficient weight"
    },
    "grad_correction_coef_weight": {
        "shape": [
            "altup_num_inputs",
            "altup_num_inputs"
        ],
        "dtype": "float32",
        "description": "Gradient w.r.t. correction coefficient weight"
    },
    "grad_router_weight": {
        "shape": [
            "altup_num_inputs",
            "hidden_size"
        ],
        "dtype": "float32",
        "description": "Gradient w.r.t. router weight"
    },
    "grad_norm_weight": {
        "shape": [
            "hidden_size"
        ],
        "dtype": "float32",
        "description": "Gradient w.r.t. norm weight"
    }
},

